style.css:
@-moz-document domain("deltamath.com") {
/* Main Background */
    body, .container, .main-content {
        background-color: #ff1493 !important; /* Hot Pink */
    }

    /* Header and Navigation */
    .navbar, .header, .top-bar {
        background-color: #ff007f !important;
        color: #fff !important;
    }

    /* Sidebar and Menus */
    .sidebar, .menu, .dropdown-menu, .panel {
        background-color: #ff66b2 !important;
        color: #fff !important;
    }

    /* Cards and Content Boxes */
    .card, .panel-body, .content-box {
        background-color: #ff33a6 !important;
        color: #fff !important;
    }

    /* Buttons */
    .btn, .btn-primary, .btn-secondary, .button {
        background-color: #ff007f !important;
        color: #fff !important;
        border-color: #ff0055 !important;
    }

    /* Hover Effects */
    .btn:hover, .button:hover, .dropdown-item:hover {
        background-color: #cc0066 !important;
    }

    /* Input Fields */
    input, textarea, select {
        background-color: #ff99cc !important;
        color: #000 !important;
        border-color: #ff66b2 !important;
    }

    /* Text Colors */
    * {
        color: #fff !important; /* White text */
    }

    /* Disable Text Selection and Background Highlighting */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
